def has_adjacent_pair_h(r, grid):
    """Does row r have adjacent 4s?"""
    cols_of_4 = [c for c in range(len(grid[0])) if grid[r][c] == 4]
    for i in range(len(cols_of_4) - 1):
        if cols_of_4[i+1] == cols_of_4[i] + 1:
            return True
    return False

def has_adjacent_pair_v(c, grid):
    """Does col c have adjacent 4s?"""
    rows_of_4 = [r for r in range(len(grid)) if grid[r][c] == 4]
    for i in range(len(rows_of_4) - 1):
        if rows_of_4[i+1] == rows_of_4[i] + 1:
            return True
    return False

