    print(f"  Row {r}: {has_adjacent_pair_h(r, demo_input)}")

for c in range(26):
    if any(demo_input[r][c] == 4 for r in range(h)):
        print(f"  Col {c}: {has_adjacent_pair_v(c, demo_input)}")

